// Embedded MCC artwork normalized to 512-by-512 PNG; no runtime network dependency.
export const MccRed = new Blob([Uint8Array.from(atob(''), character => character.charCodeAt(0))], { type: 'image/png' })
export const McciIsland = new Blob([Uint8Array.from(atob(''), character => character.charCodeAt(0))], { type: 'image/png' })
export const McciBlue = new Blob([Uint8Array.from(atob(''), character => character.charCodeAt(0))], { type: 'image/png' })
export const MccIconColor = new Blob([Uint8Array.from(atob(''), character => character.charCodeAt(0))], { type: 'image/png' })
export const MccInitialsIconColor = new Blob([Uint8Array.from(atob(''), character => character.charCodeAt(0))], { type: 'image/png' })
